-- Gold Query
SELECT "date" FROM (SELECT t2.crossing, t2."date" FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_fifa_api_id = t2.player_fifa_api_id WHERE t1.player_name = 'Kevin Constant' ORDER BY t2.crossing DESC, t1.id NULLS LAST, t2.id NULLS LAST) ORDER BY date DESC, "date" NULLS LAST LIMIT 1;

